from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]/'assets'/'objects'
ROOT.mkdir(parents=True,exist_ok=True)
ink='#655347'
def svg(name,w,h,body):
    (ROOT/f'{name}.svg').write_text(f'''<svg xmlns="http://www.w3.org/2000/svg" width="{w+24}" height="{h+24}" viewBox="-12 -12 {w+24} {h+24}"><g stroke="{ink}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round">{body}</g></svg>''')
def rect(x,y,w,h,c,r=3,extra=''):
    return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{c}" {extra}/>'
def line(x1,y1,x2,y2,c=None,extra=''):
    return f'<path d="M{x1} {y1}L{x2} {y2}" fill="none" stroke="{c or ink}" {extra}/>'
def circ(x,y,r,c,extra=''):
    return f'<circle cx="{x}" cy="{y}" r="{r}" fill="{c}" {extra}/>'
